namespace mlir {
namespace ascendc {
#define GEN_PASS_DEF_PRIVATIZEFUNC
#include "ascir/Dialect/Asc/Transforms/Passes.h.inc"
} // namespace ascendc
} // namespace mlir

using namespace mlir;

namespace {

struct PrivatizeFuncPass : public ascendc::impl::PrivatizeFuncBase<PrivatizeFuncPass> {
    void runOnOperation() override
    {
        getOperation().walk([](func::FuncOp op) {
            if (!op->hasAttrOfType<UnitAttr>(ascendc::attr::global)) {
                op.setPrivate();
            } else if (!op.isDeclaration()) {
                op.setPublic();
            }
        });
    }
};

} // namespace

namespace mlir {
namespace ascendc {
std::unique_ptr<Pass> createPrivatizeFuncPass() { return std::make_unique<PrivatizeFuncPass>(); }
} // namespace ascendc
} // namespace mlir

