class JITFunction(Function[P, T]):
    codegen: Type[FunctionVisitor] = FunctionVisitor
    compiler: Type[Compiler] = Compiler
    launcher: Type[Launcher] = Launcher

    def __init__(self, fn: Callable[P, T], **options):
        super().__init__(fn)
        clashed_args = self.get_clashed_args(fn)
        if clashed_args:
            raise RuntimeError("The following argument names conflict with JIT configuration options: " +
                               ", ".join(clashed_args))
        unknown_options = set(options).difference(self.get_config_keywords())
        if unknown_options:
            raise RuntimeError("The following option names are unknown: " + ", ".join(unknown_options))
        self.default_options: Dict[str, Any] = options
        self.launch_options = LaunchOptions()
        self.kernel_cache = {}

    def __getitem__(self, user_launch_options: Union[int, tuple]) -> Callable:
        try:
            if isinstance(user_launch_options, int):
                self.launch_options = LaunchOptions(core_num=user_launch_options)
            else:
                self.launch_options = LaunchOptions(*user_launch_options)
        except Exception as e:
            raise TypeError("Parse user launch options failed") from e
        else:
            return self._run

    @staticmethod
    def get_clashed_args(fn: Callable) -> List[str]:
        keywords = set(__class__.get_config_keywords())
        signature = inspect.signature(fn)
        keywords.intersection_update(signature.parameters)
        return list(keywords)

    @staticmethod
    def get_arg_type(value: Any) -> BaseArgType:
        if isinstance(value, bool):
            return PlainArgType(KT.bool_)
        if isinstance(value, int):
            return PlainArgType(KT.int_)
        if isinstance(value, float):
            return PlainArgType(KT.float_)
        if isinstance(value, np.ndarray):
            return PointerArgType(DataType(str(np.dtype(value.dtype))))
        if isinstance(value, np.generic):
            return PlainArgType(DataType(str(value.dtype)))
        if isinstance(value, Struct):
            return StructArgType(type(value))
        try:
            import torch
            if isinstance(value, torch.Tensor):
                dtype_str = str(value.dtype)
                if dtype_str.startswith("torch."):
                    dtype_str = dtype_str[6:]
                return PointerArgType(DataType(dtype_str))
        except ModuleNotFoundError:
            pass
        # Mock arguments
        if isinstance(value, MockTensor):
            return PointerArgType(value.dtype)
        if isinstance(value, MockValue):
            return PlainArgType(value.dtype)
        raise TypeError(f"Argument type in JIT function is not supported: {value.__class__.__name__}")

    @staticmethod
    def extract_kwargs(dataclass: Type, base_kwargs: Dict[str, Any]) -> Any:
        keywords = map(lambda f: f.name, fields(dataclass))
        kwargs = {}
        for keyword in keywords:
            if keyword in base_kwargs:
                kwargs[keyword] = base_kwargs[keyword]
                del base_kwargs[keyword]
        return dataclass(**kwargs)

    @staticmethod
    def create_context() -> ir.Context:
        context = ir.Context()
        context.disable_multithreading()
        ir.load_dialects(context)
        return context

    @staticmethod
    def get_arg_dtype(arg_type: BaseArgType) -> str:
        if isinstance(arg_type, PointerArgType):
            return str(arg_type.dtype)
        if isinstance(arg_type, PlainArgType):
            return str(arg_type.dtype)
        if isinstance(arg_type, IRArgType):
            return str(arg_type.py_type)

    passes.common.add_canonicalizer(pm)
    passes.common.add_cse(pm)

def _schedule_optimizing(self, pm: passes.PassManager) -> None:
    passes.common.add_licm(pm)
    passes.common.add_sccp(pm)
    passes.common.add_canonicalizer(pm)
    if self.options.insert_sync:
        passes.ascendc.add_erase_sync(pm)
        passes.ascendc.add_hoist_que_bind(pm)
        passes.ascendc.add_insert_sync(pm)
        passes.ascendc.add_unify_pipe(pm)
        passes.common.add_canonicalizer(pm)

@staticmethod
def _run_cmd(cmd: List[str], cmd_type: str) -> None:
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    out, _ = proc.communicate()
    is_compile_cmd = cmd_type == "compile"
    if proc.returncode != 0:
        if is_compile_cmd and "--cce-aicore-only" in cmd:
            cmd_idx_four = 4
            cmd_idx_five = 5
            cmd.insert(cmd_idx_four, "-mllvm")
            cmd.insert(cmd_idx_five, "-disable-machine-licm")
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            out, ret = proc.communicate()
            if ret == 0:
                return
        raise RuntimeError("{} failed!\nError message is {}\nPlease rerun {}".format(
            cmd_type, out.decode(), (" ".join(cmd))))

@final
def run(self, mod: ir.ModuleOp, func_name: str) -> CompiledKernel:
    utils.FileUtils.dump_file(self.dump_dir, "codegen.mlir", str(mod))
    if self.options.run_passes:
        self.run_passes(mod)
    utils.FileUtils.dump_file(self.dump_dir, "ascir.mlir", str(mod))
    source = self.run_translation(mod)
    if self.enable_debug:
        source = self._gen_init_dump_code(source, func_name)
    utils.FileUtils.dump_file(self.dump_dir, "ascendc.cpp", source)
    kernel_args = ir.get_kernel_arg_attrs(mod)
    return self.run_compilation(source, kernel_args)

def run_passes(self, mod: ir.ModuleOp) -> None:
    pm = passes.PassManager(mod.get_context())
    pm.enable_verifier()
    if self.options.print_ir_before_all:
        pm.enable_printing()
    if self.options.insert_sync is None:
        self.options.insert_sync = mod.need_insert_sync()
    self._schedule_passes(pm)
    pm.run(mod)
    if self.options.kernel_type is None:
        if mod.op.has_unit_attr("asc.compile_mix"):
            self.options.kernel_type = KernelType.AIC_ONLY if self.options.matmul_cube_only else\
                                       KernelType.MIX_AIC_1_2
        else:
            self.options.kernel_type = KernelType.AIV_ONLY
    self.enable_debug = mod.op.has_unit_attr("asc.enable_debug") and\
        str(os.environ.get("ASCENDC_DUMP", "True")).lower() == "true"

def run_compilation(self, source: str, kernel_args: Optional[Tuple[ir.KernelArgument]] = None) -> CompiledKernel:
    with tempfile.TemporaryDirectory(prefix="pyasc_compiler_") as tmp_dir:
        src = Path(tmp_dir) / "input.cce"
        src.write_text(source)
        dst = Path(tmp_dir) / "output.o"
        self._gen_dst_kernel(tmp_dir, src, dst)
        if self.dump_dir is not None:
            shutil.copyfile(dst, self.dump_dir / "binary.o")
        if self.options.kernel_type in [KernelType.MIX_AIC_1_1, KernelType.MIX_AIC_1_2]:
            core_type = CoreType.AiCore
        elif self.options.kernel_type in [
                KernelType.AIV_ONLY, KernelType.MIX_AIV_HARD_SYNC, KernelType.MIX_AIV_1_0
        ]:
            core_type = CoreType.VectorCore
        else:
            core_type = CoreType.CubeCore
        return CompiledKernel(dst.read_bytes(), core_type, self.enable_debug, kernel_args)

